import { createClient } from "npm:@supabase/supabase-js@2.50.0";
import { SyncOrchestrator } from './sync-orchestrator.ts';
import { ResponseBuilder } from './response-builder.ts';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response(null, { headers: corsHeaders });
  }

  try {
    console.log('🚀 Iniciando sincronización con Avantio (modo background)...');

    const avantioApiToken = Deno.env.get('AVANTIO_API_TOKEN');

    if (!avantioApiToken) {
      console.log('⚠️ AVANTIO_API_TOKEN no configurado');
      return new Response(
        JSON.stringify(ResponseBuilder.buildConfigurationErrorResponse()),
        {
          headers: { ...corsHeaders, 'Content-Type': 'application/json' },
          status: 400
        }
      );
    }

    const supabaseUrl = Deno.env.get('SUPABASE_URL') ?? '';
    const supabaseServiceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '';

    // Parse trigger metadata from request body (cron sends triggered_by/schedule_name)
    let triggerMeta: { triggered_by?: string; schedule_name?: string; schedule_id?: string; source?: string } = {};
    try {
      if (req.headers.get('content-type')?.includes('application/json')) {
        const body = await req.json();
        if (body && typeof body === 'object') triggerMeta = body;
      }
    } catch (_) {
      // ignore body parse errors
    }

    // CONCURRENCY GUARD: refuse if there's already a running sync started <30 min ago.
    // Prevents cron + manual triggers from stacking and competing for CPU.
    const guardClient = createClient(supabaseUrl, supabaseServiceKey);
    const thirtyMinAgo = new Date(Date.now() - 30 * 60 * 1000).toISOString();
    const { data: runningSyncs } = await guardClient
      .from('avantio_sync_logs')
      .select('id, sync_started_at, triggered_by')
      .eq('status', 'running')
      .gte('sync_started_at', thirtyMinAgo)
      .order('sync_started_at', { ascending: false })
      .limit(1);

    if (runningSyncs && runningSyncs.length > 0) {
      const existing = runningSyncs[0];
      console.log(`⏸️ Sync rechazado: ya hay una sincronización en curso (id=${existing.id})`);
      return new Response(
        JSON.stringify({
          success: false,
          status: 'skipped',
          message: 'Ya hay una sincronización Avantio en curso. Espera a que termine antes de lanzar otra.',
          running_sync_id: existing.id,
          running_since: existing.sync_started_at,
        }),
        {
          headers: { ...corsHeaders, 'Content-Type': 'application/json' },
          status: 409
        }
      );
    }

    const orchestrator = new SyncOrchestrator(supabaseUrl, supabaseServiceKey);

    // Initialize sync log SYNCHRONOUSLY so we can return its ID immediately
    await orchestrator.initializeSyncLog(triggerMeta);
    const syncLogId = orchestrator.getSyncLogId();

    // Run the heavy work in the background when the runtime exposes waitUntil.
    // Some Supabase runtime versions do not expose EdgeRuntime, so fall back to
    // awaiting the same job instead of throwing before returning the response.
    const syncWork = (async () => {
      try {
        await orchestrator.performSync(avantioApiToken);
        await orchestrator.finalizeSyncLog(true);
        console.log('✅ Sincronización Avantio completada exitosamente (background)');
      } catch (error) {
        console.error('❌ Error durante la sincronización (background):', error);
        try {
          await orchestrator.finalizeSyncLog(false, error as Error);
        } catch (finalizeError) {
          console.error('❌ Error finalizando log:', finalizeError);
        }
      }
    })();

    type EdgeRuntimeWithWaitUntil = {
      waitUntil?: (promise: Promise<unknown>) => void;
    };
    const edgeRuntime = (globalThis as typeof globalThis & {
      EdgeRuntime?: EdgeRuntimeWithWaitUntil;
    }).EdgeRuntime;

    if (typeof edgeRuntime?.waitUntil === 'function') {
      edgeRuntime.waitUntil(syncWork);
    } else {
      await syncWork;
    }

    // Return 202 Accepted with sync_log_id so the client can poll for status
    return new Response(
      JSON.stringify({
        success: true,
        status: 'running',
        message: 'Sincronización iniciada en segundo plano. Consulta avantio_sync_logs para ver el progreso.',
        sync_log_id: syncLogId
      }),
      {
        headers: { ...corsHeaders, 'Content-Type': 'application/json' },
        status: 202
      }
    );

  } catch (error) {
    console.error('❌ Error crítico:', error);
    const response = ResponseBuilder.buildCriticalErrorResponse(error);
    return new Response(JSON.stringify(response), {
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
      status: 500
    });
  }
});

import { createClient } from "npm:@supabase/supabase-js@2.50.0";
import { SyncStats } from './types.ts';
import { fetchAllAvantioReservations } from './avantio-api.ts';
import { ReservationProcessor } from './reservation-processor.ts';
import { createSyncLog, updateSyncLog, preloadPropertiesCache, clearPropertiesCache, preloadReservationsAndTasksCache, clearReservationsAndTasksCache } from './database-operations.ts';

const SYNC_WORK_BUDGET_MS = 110000;
const SOURCE_FETCH_BUDGET_MS = 70000;

export class SyncOrchestrator {
  private supabase;
  private processor: ReservationProcessor;
  private syncLogId: string | null = null;
  private syncDeadlineAt = 0;
  private stats: SyncStats = {
    reservations_processed: 0,
    new_reservations: 0,
    updated_reservations: 0,
    cancelled_reservations: 0,
    tasks_created: 0,
    tasks_cancelled: 0,
    tasks_modified: 0,
    errors: [],
    tasks_details: [],
    tasks_cancelled_details: [],
    tasks_modified_details: [],
    reservations_details: []
  };

  constructor(supabaseUrl: string, supabaseServiceKey: string) {
    this.supabase = createClient(supabaseUrl, supabaseServiceKey);
    this.processor = new ReservationProcessor(supabaseUrl, supabaseServiceKey);
  }

  async initializeSyncLog(triggerMeta?: { triggered_by?: string; schedule_name?: string }): Promise<void> {
    const syncLog = await createSyncLog(triggerMeta);
    this.syncLogId = syncLog.id;
    console.log(`📝 Log de sincronización iniciado: ${this.syncLogId} (trigger=${triggerMeta?.triggered_by || 'manual'})`);
  }

  getSyncLogId(): string | null {
    return this.syncLogId;
  }

  private assertWithinSyncBudget(phase: string): void {
    if (this.syncDeadlineAt > 0 && Date.now() >= this.syncDeadlineAt) {
      throw new Error(`Global Avantio sync budget exhausted before phase: ${phase}`);
    }
  }

  async performSync(token: string): Promise<void> {
    this.syncDeadlineAt = Date.now() + SYNC_WORK_BUDGET_MS;
    const sourceDeadlineAt = Math.min(
      this.syncDeadlineAt,
      Date.now() + SOURCE_FETCH_BUDGET_MS,
    );
    console.log('🚀 Iniciando sincronización con Avantio PMS v1...');

    // CRITICAL: Preload all properties into in-memory cache (1 query instead of thousands)
    await preloadPropertiesCache();

    try {
      // Fetch all reservations using real API (pagination + detail included).
      // The source phase gets a smaller budget so DB processing and log finalization keep headroom.
      const reservations = await fetchAllAvantioReservations(token, { deadlineAt: sourceDeadlineAt });
      this.assertWithinSyncBudget('preload reservations and tasks');

      console.log(`📊 Total de reservas a procesar: ${reservations.length}`);

      // Compute window for caching reservations & tasks (min arrival → max departure)
      const today = new Date().toISOString().slice(0, 10);
      let minDate = today;
      let maxDate = today;
      for (const r of reservations) {
        if (r.departureDate && r.departureDate > maxDate) maxDate = r.departureDate;
        if (r.arrivalDate && r.arrivalDate < minDate) minDate = r.arrivalDate;
      }
      await preloadReservationsAndTasksCache(minDate, maxDate);

      // Process each reservation sequentially (matches stable behaviour pre-2026-04-24)
      for (let i = 0; i < reservations.length; i++) {
        this.assertWithinSyncBudget(`process reservation ${i + 1}/${reservations.length}`);
        try {
          await this.processor.processReservation(
            reservations[i],
            this.stats,
            i,
            reservations.length,
            this.syncLogId
          );
        } catch (error) {
          console.error(`❌ Error procesando reserva ${reservations[i].id}:`, error);
          this.stats.errors.push(`Error en reserva ${reservations[i].id}: ${error.message}`);
        }
      }

      // DEDUP: Remove duplicate tasks for same property/date
      this.assertWithinSyncBudget('deduplicate tasks');
      await this.deduplicateTasks();

      // REPAIR: Check for reservations in DB with NULL task_id that should have tasks
      this.assertWithinSyncBudget('repair missing tasks');
      await this.repairMissingTasks();

      // CLEANUP: Remove tasks for REQUESTED reservations past check-in time
      this.assertWithinSyncBudget('cleanup expired requested tasks');
      await this.cleanupExpiredRequestedTasks();

      console.log('✅ Sincronización completada');
    } finally {
      // Always free memory
      clearPropertiesCache();
      clearReservationsAndTasksCache();
    }
  }

  private async deduplicateTasks(): Promise<void> {
    console.log('🔍 Buscando tareas duplicadas (misma propiedad y fecha)...');
    
    const today = new Date().toISOString().slice(0, 10);
    
    // Find Avantio tasks (green) with duplicates on same property+date
    const { data: duplicates, error } = await this.supabase
      .from('tasks')
      .select('id, propiedad_id, date, property, cleaner_id')
      .eq('background_color', '#10B981')
      .gte('date', today)
      .not('propiedad_id', 'is', null)
      .order('created_at', { ascending: true });

    if (error || !duplicates) {
      console.log('❌ Error buscando duplicados:', error);
      return;
    }

    // Group by propiedad_id + date
    const groups = new Map<string, typeof duplicates>();
    for (const task of duplicates) {
      const key = `${task.propiedad_id}_${task.date}`;
      if (!groups.has(key)) groups.set(key, []);
      groups.get(key)!.push(task);
    }

    let removedCount = 0;
    for (const [key, tasks] of groups) {
      this.assertWithinSyncBudget(`deduplicate task group ${key}`);
      if (tasks.length <= 1) continue;

      // Keep the first one (or one with a cleaner assigned)
      const sorted = tasks.sort((a, b) => {
        if (a.cleaner_id && !b.cleaner_id) return -1;
        if (!a.cleaner_id && b.cleaner_id) return 1;
        return 0;
      });
      
      const keepTask = sorted[0];
      const removeTasks = sorted.slice(1);

      console.log(`⚠️ Duplicados para ${keepTask.property} (${keepTask.date}): ${tasks.length} tareas. Manteniendo ${keepTask.id}`);

      for (const removeTask of removeTasks) {
        // Point any avantio_reservations referencing this task to the kept task
        await this.supabase
          .from('avantio_reservations')
          .update({ task_id: keepTask.id })
          .eq('task_id', removeTask.id);

        // Delete the duplicate task
        await this.supabase
          .from('tasks')
          .delete()
          .eq('id', removeTask.id);

        removedCount++;
        console.log(`🗑️ Tarea duplicada eliminada: ${removeTask.id}`);
      }

      // After merging, check if the kept task has "POSIBLE - " prefix but confirmed reservations exist
      const { data: linkedReservations } = await this.supabase
        .from('avantio_reservations')
        .select('status')
        .eq('task_id', keepTask.id);

      if (linkedReservations && keepTask.property?.includes('POSIBLE - ')) {
        const hasConfirmed = linkedReservations.some(
          r => !['REQUESTED', 'CANCELLED', 'UNAVAILABLE'].includes(r.status?.toUpperCase())
        );
        if (hasConfirmed) {
          const newName = keepTask.property.replace('POSIBLE - ', '');
          await this.supabase
            .from('tasks')
            .update({ property: newName })
            .eq('id', keepTask.id);
          console.log(`✏️ Prefijo POSIBLE eliminado de tarea fusionada ${keepTask.id}: ${newName}`);
        }
      }
    }

    if (removedCount > 0) {
      console.log(`✅ ${removedCount} tareas duplicadas eliminadas`);
    } else {
      console.log('✅ No hay tareas duplicadas');
    }
  }

  private async repairMissingTasks(): Promise<void> {
    console.log('🔧 Verificando reservas sin tarea asignada...');
    
    const today = new Date().toISOString().slice(0, 10);
    
    // CRITICAL: Excluir REQUESTED (POSIBLE) — esas reservas no deben crear tarea por diseño
    // y antes inflaban la lista a 1000+ entradas inútiles agotando CPU.
    // Paginar para no quedar topados al límite de 1000 de Supabase.
    const PAGE = 500;
    let from = 0;
    const orphanedReservations: any[] = [];
    while (true) {
      this.assertWithinSyncBudget('page orphaned reservations');
      const { data: page, error } = await this.supabase
        .from('avantio_reservations')
        .select('*, properties!avantio_reservations_property_id_fkey(*)')
        .is('task_id', null)
        .not('status', 'in', '("cancelled","CANCELLED","UNAVAILABLE","REQUESTED","PENDING","TENTATIVE")')
        .gte('departure_date', today)
        .not('property_id', 'is', null)
        .range(from, from + PAGE - 1);

      if (error) {
        console.error('❌ Error buscando reservas huérfanas:', error);
        break;
      }
      if (!page || page.length === 0) break;
      orphanedReservations.push(...page);
      if (page.length < PAGE) break;
      from += PAGE;
    }

    if (orphanedReservations.length === 0) {
      console.log('✅ No hay reservas sin tarea');
      return;
    }

    console.log(`⚠️ Encontradas ${orphanedReservations.length} reservas confirmadas sin tarea. Reparando...`);

    for (const reservation of orphanedReservations) {
      this.assertWithinSyncBudget(`repair reservation ${reservation.avantio_reservation_id}`);
      if (!reservation.properties) continue;
      
      try {
        const { createTaskForReservation } = await import('./database-operations.ts');
        
        const avantioReservation = {
          id: reservation.avantio_reservation_id,
          accommodationId: reservation.accommodation_id || '',
          accommodationName: reservation.accommodation_name || '',
          accommodationInternalName: '',
          status: reservation.status,
          arrivalDate: reservation.arrival_date,
          departureDate: reservation.departure_date,
          reservationDate: reservation.reservation_date || '',
          cancellationDate: reservation.cancellation_date || '',
          nights: reservation.nights || 1,
          adults: reservation.adults || 2,
          children: reservation.children || 0,
          guestName: reservation.guest_name,
        };

        const { shouldCreateTaskForReservation } = await import('./reservation-validator.ts');
        if (!shouldCreateTaskForReservation(avantioReservation)) continue;

        const task = await createTaskForReservation(avantioReservation, reservation.properties);
        
        await this.supabase
          .from('avantio_reservations')
          .update({ task_id: task.id })
          .eq('id', reservation.id);

        this.stats.tasks_created++;
        if (!this.stats.tasks_details) this.stats.tasks_details = [];
        this.stats.tasks_details.push({
          reservation_id: reservation.avantio_reservation_id,
          property_name: reservation.properties.nombre,
          task_id: task.id,
          task_date: reservation.departure_date,
          guest_name: reservation.guest_name,
          accommodation_id: reservation.accommodation_id || '',
          status: `REPAIRED-${reservation.status}`
        });

        console.log(`✅ Tarea reparada: ${task.id} para reserva ${reservation.avantio_reservation_id} (${reservation.properties.nombre})`);
      } catch (repairError) {
        console.error(`❌ Error reparando reserva ${reservation.avantio_reservation_id}:`, repairError);
        this.stats.errors.push(`Error reparando tarea para ${reservation.avantio_reservation_id}: ${repairError.message}`);
      }
    }
  }

  private async cleanupExpiredRequestedTasks(): Promise<void> {
    console.log('🧹 Verificando tareas POSIBLE (REQUESTED) expiradas...');

    // Current date/time in Europe/Madrid
    const nowMadrid = new Date(new Date().toLocaleString('en-US', { timeZone: 'Europe/Madrid' }));
    const todayStr = `${nowMadrid.getFullYear()}-${String(nowMadrid.getMonth() + 1).padStart(2, '0')}-${String(nowMadrid.getDate()).padStart(2, '0')}`;
    const currentHour = nowMadrid.getHours();
    const currentMinute = nowMadrid.getMinutes();

    // Query: REQUESTED reservations with a task, arrival_date <= today (paginado)
    const PAGE = 500;
    let from = 0;
    const expiredRequested: any[] = [];
    while (true) {
      this.assertWithinSyncBudget('page expired requested reservations');
      const { data: page, error } = await this.supabase
        .from('avantio_reservations')
        .select('*, properties!avantio_reservations_property_id_fkey(*)')
        .ilike('status', 'REQUESTED')
        .not('task_id', 'is', null)
        .lte('arrival_date', todayStr)
        .range(from, from + PAGE - 1);

      if (error) {
        console.error('❌ Error buscando reservas REQUESTED expiradas:', error);
        break;
      }
      if (!page || page.length === 0) break;
      expiredRequested.push(...page);
      if (page.length < PAGE) break;
      from += PAGE;
    }

    if (expiredRequested.length === 0) {
      console.log('✅ No hay tareas POSIBLE expiradas');
      return;
    }

    // Filter: only those where arrival_date < today, OR arrival_date == today AND current time >= 17:00
    const toCleanup = expiredRequested.filter(r => {
      if (r.arrival_date < todayStr) return true;
      // arrival_date === todayStr
      return currentHour > 17 || (currentHour === 17 && currentMinute >= 0);
    });

    if (toCleanup.length === 0) {
      console.log('✅ No hay tareas POSIBLE expiradas (aún no son las 17:00)');
      return;
    }

    console.log(`⚠️ Eliminando ${toCleanup.length} tareas POSIBLE expiradas...`);

    const { deleteTaskIfPending } = await import('./database-operations.ts');

    for (const reservation of toCleanup) {
      this.assertWithinSyncBudget(`cleanup requested reservation ${reservation.avantio_reservation_id}`);
      try {
        // CHECK: Are there sibling reservations (non-REQUESTED, non-CANCELLED) sharing this task?
        const { data: siblings } = await this.supabase
          .from('avantio_reservations')
          .select('id, status')
          .eq('task_id', reservation.task_id)
          .neq('id', reservation.id)
          .not('status', 'ilike', 'REQUESTED')
          .not('status', 'ilike', 'CANCELLED')
          .not('status', 'ilike', 'UNAVAILABLE');

        if (siblings && siblings.length > 0) {
          // Sibling confirmed reservations exist — do NOT delete the task
          console.log(`⚠️ Tarea ${reservation.task_id} compartida con ${siblings.length} reservas activas. Solo desvinculando reserva POSIBLE ${reservation.avantio_reservation_id}`);

          // Unlink only the REQUESTED reservation
          await this.supabase
            .from('avantio_reservations')
            .update({ task_id: null })
            .eq('id', reservation.id);

          // Remove "POSIBLE - " prefix from task name if present
          const { data: taskData } = await this.supabase
            .from('tasks')
            .select('property')
            .eq('id', reservation.task_id)
            .single();

          if (taskData?.property?.includes('POSIBLE - ')) {
            await this.supabase
              .from('tasks')
              .update({ property: taskData.property.replace('POSIBLE - ', '') })
              .eq('id', reservation.task_id);
            console.log(`✏️ Prefijo POSIBLE eliminado de tarea ${reservation.task_id}`);
          }

          continue; // Skip deletion
        }

        // No siblings — safe to delete the task
        const { data: taskData } = await this.supabase
          .from('tasks')
          .select('*, cleaners(id, name, email)')
          .eq('id', reservation.task_id)
          .single();

        const deleted = await deleteTaskIfPending(reservation.task_id);
        if (!deleted) {
          console.log(`🛡️ Tarea POSIBLE ${reservation.task_id} conservada: ya comenzó, terminó o su estado no es seguro para borrar`);
          continue;
        }

        const { error: unlinkError } = await this.supabase
          .from('avantio_reservations')
          .update({ task_id: null })
          .eq('id', reservation.id);
        if (unlinkError) throw unlinkError;

        // Send cancellation email if cleaner was assigned
        if (taskData?.cleaner_id && taskData?.cleaners?.email) {
          console.log(`📧 Enviando email de cancelación POSIBLE expirada a ${taskData.cleaners.name}`);
          try {
            const { error: emailError } = await this.supabase.functions.invoke('send-task-unassignment-email', {
              body: {
                taskId: reservation.task_id,
                cleanerEmail: taskData.cleaners.email,
                cleanerName: taskData.cleaners.name,
                taskData: {
                  property: taskData.property || reservation.properties?.nombre || '',
                  address: taskData.address || '',
                  date: taskData.date || reservation.departure_date,
                  startTime: taskData.start_time || '',
                  endTime: taskData.end_time || '',
                  type: taskData.service_type || '',
                  notes: `Reserva POSIBLE expirada (no confirmada antes del check-in). Huésped: ${reservation.guest_name}`
                },
                reason: 'cancelled'
              }
            });
            if (emailError) throw emailError;
          } catch (emailError) {
            console.error(`❌ Error enviando email cancelación POSIBLE:`, emailError);
          }
        }

        this.stats.tasks_cancelled++;
        if (!this.stats.tasks_cancelled_details) this.stats.tasks_cancelled_details = [];
        this.stats.tasks_cancelled_details.push({
          reservation_id: reservation.avantio_reservation_id,
          property_name: reservation.properties?.nombre || reservation.accommodation_name || '',
          task_id: reservation.task_id,
          task_date: reservation.departure_date,
          guest_name: reservation.guest_name,
          accommodation_id: reservation.accommodation_id || '',
          status: `EXPIRED-REQUESTED`
        });

        console.log(`🗑️ Tarea POSIBLE eliminada: ${reservation.task_id} (reserva ${reservation.avantio_reservation_id}, ${reservation.properties?.nombre || ''})`);
      } catch (cleanupError) {
        console.error(`❌ Error eliminando tarea POSIBLE ${reservation.task_id}:`, cleanupError);
        this.stats.errors.push(`Error cleanup REQUESTED ${reservation.avantio_reservation_id}: ${cleanupError.message}`);
      }
    }
  }

  async finalizeSyncLog(success: boolean, error?: Error): Promise<void> {
    if (!this.syncLogId) return;

    const updates: any = {
      sync_completed_at: new Date().toISOString(),
      status: success ? 'completed' : 'failed',
      reservations_processed: this.stats.reservations_processed,
      new_reservations: this.stats.new_reservations,
      updated_reservations: this.stats.updated_reservations,
      cancelled_reservations: this.stats.cancelled_reservations,
      tasks_created: this.stats.tasks_created,
      tasks_cancelled: this.stats.tasks_cancelled,
      tasks_modified: this.stats.tasks_modified,
      errors: this.stats.errors.length > 0 ? this.stats.errors : null,
      tasks_details: this.stats.tasks_details?.length ? this.stats.tasks_details : null,
      tasks_cancelled_details: this.stats.tasks_cancelled_details?.length ? this.stats.tasks_cancelled_details : null,
      tasks_modified_details: this.stats.tasks_modified_details?.length ? this.stats.tasks_modified_details : null,
      reservations_details: this.stats.reservations_details?.length ? this.stats.reservations_details : null
    };

    if (error) {
      updates.errors = [...(updates.errors || []), error.message];
    }

    await updateSyncLog(this.syncLogId, updates);
    console.log(`📝 Log de sincronización finalizado: ${this.syncLogId}`);

    // Send error notification email if sync failed or had errors
    if (!success || this.stats.errors.length > 0) {
      await this.sendErrorNotificationEmail(success, error);
    }
  }

  private async sendErrorNotificationEmail(success: boolean, error?: Error): Promise<void> {
    try {
      const errorSummary = !success 
        ? `Sincronización FALLIDA: ${error?.message || 'Error desconocido'}`
        : `Sincronización completada con ${this.stats.errors.length} errores`;

      const errorDetails = this.stats.errors.slice(0, 20).join('\n');

      console.log(`📧 Enviando email de notificación de errores...`);
      
      await this.supabase.functions.invoke('send-avantio-error-email', {
        body: {
          syncLogId: this.syncLogId,
          success,
          errorSummary,
          errorDetails,
          stats: {
            reservations_processed: this.stats.reservations_processed,
            new_reservations: this.stats.new_reservations,
            updated_reservations: this.stats.updated_reservations,
            tasks_created: this.stats.tasks_created,
            tasks_cancelled: this.stats.tasks_cancelled,
            tasks_modified: this.stats.tasks_modified,
            errors_count: this.stats.errors.length
          },
          tasks_details: this.stats.tasks_details || [],
          tasks_cancelled_details: this.stats.tasks_cancelled_details || [],
          tasks_modified_details: this.stats.tasks_modified_details || [],
          timestamp: new Date().toISOString()
        }
      });
      console.log(`✅ Email de notificación enviado`);
    } catch (emailError) {
      console.error(`❌ Error enviando email de notificación:`, emailError);
    }
  }

  getStats(): SyncStats {
    return this.stats;
  }
}

