import { AvantioReservation } from './types.ts';

const API_BASE_URL = 'https://api.avantio.pro/pms/v1';
const MAX_RETRIES = 4;
const TIMEOUT_MS = 30000;
const FUTURE_DAYS = 30;
const MAX_PAGES = 100;
const PAGE_SIZE = 200;

export interface HttpGetOptions {
  retries?: number;
  timeoutMs?: number;
  deadlineAt?: number;
  fetchImpl?: typeof fetch;
  sleep?: (milliseconds: number) => Promise<void>;
}

interface AvantioApiPayload {
  data?: unknown;
  _links?: { next?: string | null };
  meta?: unknown;
  _meta?: unknown;
  pagination?: unknown;
  [key: string]: unknown;
}

export interface AvantioFetchOptions {
  deadlineAt?: number;
  fetchImpl?: typeof fetch;
  sleep?: (milliseconds: number) => Promise<void>;
}

export class AvantioSourceBudgetExceededError extends Error {}
class NonRetriableAvantioError extends Error {}

function requestLabel(url: string): string {
  try {
    const parsed = new URL(url);
    return `${parsed.pathname}${parsed.search}`;
  } catch {
    return url;
  }
}

function formatDateSimple(dateString: string | undefined | null): string {
  if (!dateString) return '';
  try { return String(dateString).split('T')[0]; } catch { return ''; }
}

function todayISO(): string {
  return new Date().toISOString().slice(0, 10);
}

function addDaysISO(baseISO: string, deltaDays: number): string {
  const d = new Date(baseISO + 'T00:00:00Z');
  d.setUTCDate(d.getUTCDate() + deltaDays);
  return d.toISOString().slice(0, 10);
}

function headersAvantio(token: string): Record<string, string> {
  return {
    'accept': 'application/json',
    'X-Avantio-Auth': token
  };
}

function calculateNights(checkIn: string, checkOut: string): number {
  if (!checkIn || !checkOut) return 1;
  const start = new Date(checkIn);
  const end = new Date(checkOut);
  if (isNaN(start.getTime()) || isNaN(end.getTime())) return 1;
  const diffDays = Math.ceil(Math.abs(end.getTime() - start.getTime()) / (1000 * 60 * 60 * 24));
  return diffDays || 1;
}

function norm(s: unknown): string {
  return String(s ?? '').trim();
}

export async function httpGet(
  url: string,
  headers: Record<string, string>,
  options: HttpGetOptions = {},
): Promise<AvantioApiPayload | null> {
  const retries = options.retries ?? MAX_RETRIES;
  const timeoutMs = options.timeoutMs ?? TIMEOUT_MS;
  const fetchImpl = options.fetchImpl ?? fetch;
  const sleep = options.sleep ?? ((milliseconds: number) => new Promise(resolve => setTimeout(resolve, milliseconds)));
  const label = requestLabel(url);
  const budgetError = () => new AvantioSourceBudgetExceededError(
    `Global Avantio source budget exhausted before completing GET ${label}`,
  );

  for (let attempt = 1; attempt <= retries; attempt++) {
    const remainingMs = options.deadlineAt === undefined
      ? Number.POSITIVE_INFINITY
      : options.deadlineAt - Date.now();
    if (remainingMs <= 0) throw budgetError();

    const attemptTimeoutMs = Math.max(1, Math.min(timeoutMs, remainingMs));
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), attemptTimeoutMs);

    try {
      const response = await fetchImpl(url, {
        method: 'GET',
        headers,
        signal: controller.signal,
      });

      if (response.ok) {
        const text = await response.text();
        try { return JSON.parse(text); } catch { return null; }
      }

      const errorText = await response.text();
      const message = `API Error ${response.status}: ${errorText.slice(0, 400)}`;
      if (response.status >= 400 && response.status < 500 && response.status !== 429) {
        throw new NonRetriableAvantioError(message);
      }
      throw new Error(message);
    } catch (error) {
      if (error instanceof NonRetriableAvantioError) throw error;

      const isTimeout = error instanceof Error && error.name === 'AbortError';
      const deadlineExpired = options.deadlineAt !== undefined && Date.now() >= options.deadlineAt;
      if (deadlineExpired) throw budgetError();

      const finalError = isTimeout
        ? new Error(`Avantio request timed out after ${attempt} attempt${attempt === 1 ? '' : 's'} (${attemptTimeoutMs}ms last attempt): GET ${label}`)
        : error instanceof Error
          ? error
          : new Error(String(error));

      if (attempt >= retries) {
        if (isTimeout) {
          throw new Error(`Avantio request timed out after ${retries} attempts (${attemptTimeoutMs}ms last attempt): GET ${label}`);
        }
        throw finalError;
      }

      const waitTime = Math.pow(2, attempt) * 1000;
      if (options.deadlineAt !== undefined && Date.now() + waitTime >= options.deadlineAt) {
        throw budgetError();
      }
      console.log(
        isTimeout
          ? `⏱️ Timeout Avantio en ${label}; reintento ${attempt + 1}/${retries} en ${waitTime}ms`
          : `⏳ Error temporal Avantio en ${label}; reintento ${attempt + 1}/${retries} en ${waitTime}ms: ${finalError.message}`,
      );
      await sleep(waitTime);
    } finally {
      clearTimeout(timeoutId);
    }
  }

  throw new Error(`Avantio request failed after ${retries} attempts: GET ${label}`);
}

interface AvantioAccommodationDetail {
  name?: string;
  legalName?: string;
  internalName?: string;
  [key: string]: unknown;
}

/**
 * Get accommodation detail directly. This endpoint remains healthy even when
 * Avantio's bookings service contains records that hang on detail requests.
 */
export async function getAccommodationDetail(
  token: string,
  accommodationId: string,
  options: HttpGetOptions = {},
): Promise<AvantioAccommodationDetail | null> {
  const url = `${API_BASE_URL}/accommodations/${encodeURIComponent(String(accommodationId))}`;
  const result = await httpGet(url, headersAvantio(token), options);
  const payload = result?.data ?? result;
  if (!payload || typeof payload !== 'object') return null;
  return payload as AvantioAccommodationDetail;
}

// Cache: accommodationId -> { name, internalName }
const accommodationCache: Map<string, { name: string; internalName: string }> = new Map();

/**
 * Resolve accommodation name for a given accommodationId.
 * Uses the accommodation endpoint directly and caches the result.
 */
async function resolveAccommodationInfo(
  token: string,
  accommodationId: string,
  options: AvantioFetchOptions,
): Promise<{ name: string; internalName: string }> {
  if (accommodationCache.has(accommodationId)) {
    return accommodationCache.get(accommodationId)!;
  }

  const accommodation = await getAccommodationDetail(token, accommodationId, {
    deadlineAt: options.deadlineAt,
    fetchImpl: options.fetchImpl,
    sleep: options.sleep,
  });
  const name = norm(accommodation?.name || accommodation?.legalName || '');
  const internalName = norm(accommodation?.internalName || accommodation?.name || '');

  const info = { name, internalName };
  accommodationCache.set(accommodationId, info);
  console.log(`🏠 Accommodation ${accommodationId} -> nombre="${name}", código="${internalName}"`);

  return info;
}

/**
 * Fetch the Avantio reservations needed by both operational flows:
 * - checkout window: keeps task creation/update coverage intact;
 * - arrival window: keeps future entries available for the admin next-entry card.
 *
 * The two API results are deduplicated by Avantio reservation ID. A future arrival
 * may be stored even when its checkout is outside the task horizon; the processor
 * separately decides whether a cleaning task is due now.
 */
export async function fetchAllAvantioReservations(
  token: string,
  options: AvantioFetchOptions = {},
): Promise<AvantioReservation[]> {
  const cleanToken = token.replace(/^["'\s]+|["'\s]+$/g, '');
  const today = todayISO();
  // Avantio's departureFrom appears exclusive, so include yesterday.
  const fromDate = addDaysISO(today, -1);
  const toDate = addDaysISO(today, FUTURE_DAYS);

  interface RawItem {
    id: string;
    accommodationId: string;
    status: string;
    checkIn: string;
    checkOut: string;
    creationDate: string;
    total: number;
    currency: string;
  }

  type QueryWindow = {
    label: 'checkout' | 'arrival';
    fromParam: 'departureFrom' | 'arrivalFrom';
    toParam: 'departureTo' | 'arrivalTo';
    fromDate: string;
    toDate: string;
  };

  const queryWindows: QueryWindow[] = [
    { label: 'checkout', fromParam: 'departureFrom', toParam: 'departureTo', fromDate, toDate },
    { label: 'arrival', fromParam: 'arrivalFrom', toParam: 'arrivalTo', fromDate, toDate },
  ];
  const rawItemsById = new Map<string, RawItem>();
  let totalPages = 0;
  let totalDiscarded = 0;

  console.log(`📅 Ventanas Avantio: checkout ${fromDate}→${toDate} y entradas ${fromDate}→${toDate}`);

  for (const window of queryWindows) {
    let nextUrl: string | null = `${API_BASE_URL}/bookings?limit=${PAGE_SIZE}&sort=arrivalDate&order=asc&${window.fromParam}=${window.fromDate}&${window.toParam}=${window.toDate}`;
    let pages = 0;

    console.log(`🔎 URL inicial (${window.label}): ${nextUrl}`);

    while (nextUrl && pages < MAX_PAGES) {
      pages++;
      totalPages++;
      console.log(`📄 Página ${pages} (${window.label}): ${nextUrl}`);

      const pageObj = await httpGet(nextUrl, headersAvantio(cleanToken), {
        deadlineAt: options.deadlineAt,
        fetchImpl: options.fetchImpl,
        sleep: options.sleep,
      });
      if (!pageObj) break;

      const list = pageObj.data || [];
      if (!Array.isArray(list) || list.length === 0) break;

      if (pages === 1) {
        console.log(`📋 Primer item keys (${window.label}): ${JSON.stringify(Object.keys(list[0]))}`);
        console.log(`📋 Meta de la respuesta: ${JSON.stringify(pageObj.meta || pageObj._meta || pageObj.pagination || {}).slice(0, 500)}`);
      }

      let pageInRange = 0;
      for (const item of list) {
        if (!item?.id) continue;

        const checkOut = formatDateSimple(item?.dates?.departure || item?.dates?.checkOut || '');
        const checkIn = formatDateSimple(item?.dates?.arrival || item?.dates?.checkIn || '');
        if (!checkOut || !checkIn) continue;

        const relevantDate = window.label === 'arrival' ? checkIn : checkOut;
        if (relevantDate < window.fromDate || relevantDate > window.toDate) {
          totalDiscarded++;
          continue;
        }

        pageInRange++;
        const id = String(item.id);
        if (!rawItemsById.has(id)) {
          rawItemsById.set(id, {
            id,
            accommodationId: String(item.accommodationId || ''),
            status: norm(item.status || ''),
            checkIn,
            checkOut,
            creationDate: formatDateSimple(item.creationDate || item.createdAt || ''),
            total: item.total || 0,
            currency: item.currency || 'EUR',
          });
        }
      }

      console.log(`   ↳ ${window.label}: ${pageInRange} reservas útiles`);
      nextUrl = pageObj?._links?.next || null;
    }

    if (pages >= MAX_PAGES) {
      console.log(`⚠️ Alcanzado límite máximo de ${MAX_PAGES} páginas en ventana ${window.label}`);
    }
  }

  const rawItems = Array.from(rawItemsById.values());
  console.log(`📊 Fase 1 completada: ${rawItems.length} reservas únicas (descartadas ${totalDiscarded}, ${totalPages} páginas)`);

  // Phase 2: Resolve accommodation names (one accommodation call per unique ID)
  const uniqueAccommodationIds = new Set(rawItems.map(r => r.accommodationId).filter(Boolean));
  console.log(`🏠 ${uniqueAccommodationIds.size} alojamientos únicos a resolver`);

  let detailCalls = 0;
  for (const accId of uniqueAccommodationIds) {
    try {
      await resolveAccommodationInfo(cleanToken, accId, options);
      detailCalls++;
    } catch (err) {
      if (err instanceof AvantioSourceBudgetExceededError) throw err;
      const message = err instanceof Error ? err.message : String(err);
      console.error(`❌ Error resolviendo accommodation ${accId}: ${message}`);
      accommodationCache.set(accId, { name: '', internalName: '' });
      detailCalls++;
    }
  }

  console.log(`📊 Fase 2 completada: ${detailCalls} detail calls para ${uniqueAccommodationIds.size} alojamientos`);

  // Phase 3: Build reservations with resolved accommodation names
  const reservations: AvantioReservation[] = [];

  for (const item of rawItems) {
    const accInfo = accommodationCache.get(item.accommodationId) || { name: '', internalName: '' };

    reservations.push({
      id: item.id,
      accommodationId: item.accommodationId,
      accommodationName: accInfo.name,
      accommodationInternalName: accInfo.internalName,
      status: item.status,
      arrivalDate: item.checkIn,
      departureDate: item.checkOut,
      reservationDate: item.creationDate,
      cancellationDate: '',
      nights: calculateNights(item.checkIn, item.checkOut),
      adults: 2,
      children: 0,
      guestName: 'Huésped Desconocido',
      guestEmail: undefined,
      totalAmount: item.total,
      currency: item.currency,
      notes: ''
    });
  }

  console.log(`✅ Paginación completada. Páginas=${totalPages} | Detail calls=${detailCalls} | Reservas=${reservations.length}`);
  return reservations;
}

import { createClient } from "npm:@supabase/supabase-js@2.50.0";
import { AvantioReservation, SyncStats } from './types.ts';
import { 
  findPropertyByAvantioId, 
  getExistingReservation,
  insertReservation,
  createTaskForReservation,
  updateReservation,
  deleteTask,
  deleteTaskIfPending,
  updateTaskDate,
  updateTaskPropertyName,
  getTaskPropertyName,
  logSyncError
} from './database-operations.ts';
import { shouldCreateTaskForReservation } from './reservation-validator.ts';

export class ReservationProcessor {
  private supabase;

  constructor(supabaseUrl: string, supabaseServiceKey: string) {
    this.supabase = createClient(supabaseUrl, supabaseServiceKey);
  }

  async processReservation(
    reservation: AvantioReservation, 
    stats: SyncStats,
    reservationIndex: number,
    totalReservations: number,
    syncLogId?: string | null
  ): Promise<void> {
    // Logging silenciado para reducir consumo de CPU en runs grandes (>2000 reservas)

    // Find property (exact match, Turquoise only)
    const property = await findPropertyByAvantioId(
      reservation.accommodationId, 
      reservation.accommodationName,
      reservation.accommodationInternalName
    );
    
    if (!property) {
      const errorMsg = `Propiedad no encontrada: nombre="${reservation.accommodationName || 'N/A'}", código="${reservation.accommodationInternalName || 'N/A'}", ID=${reservation.accommodationId}`;
      stats.errors.push(errorMsg);
      
      await logSyncError('property_not_found', errorMsg, {
        accommodation_id: reservation.accommodationId,
        accommodation_name: reservation.accommodationName,
        accommodation_internal_name: reservation.accommodationInternalName,
        reservation_id: reservation.id,
        guest_name: reservation.guestName,
        departure_date: reservation.departureDate
      }, syncLogId);
      return;
    }

    

    const statusUpper = reservation.status.toUpperCase();
    const isCancelled = statusUpper === 'CANCELLED' || 
                        statusUpper === 'CANCELED' ||
                        statusUpper === 'UNAVAILABLE' ||
                        statusUpper === 'UNAVALIABLE' ||
                        !!reservation.cancellationDate;

    const existingReservation = await getExistingReservation(reservation.id);

    if (existingReservation) {
      if (isCancelled) {
        await this.handleCancelledReservation(reservation, existingReservation, property, stats, syncLogId);
      } else {
        await this.handleExistingReservation(reservation, existingReservation, property, stats, syncLogId);
      }
    } else {
      if (isCancelled) {
        await this.createCancelledReservation(reservation, property, stats, syncLogId);
      } else {
        await this.handleNewReservation(reservation, property, stats, syncLogId);
      }
    }

    stats.reservations_processed++;
  }

  private async handleNewReservation(
    reservation: AvantioReservation,
    property: any,
    stats: SyncStats,
    syncLogId?: string | null
  ): Promise<void> {
    try {
      const shouldCreate = shouldCreateTaskForReservation(reservation);
      let taskId = null;
      
      if (shouldCreate) {
        try {
          const task = await createTaskForReservation(reservation, property);
          taskId = task.id;
          stats.tasks_created++;
          
          if (!stats.tasks_details) stats.tasks_details = [];
          stats.tasks_details.push({
            reservation_id: reservation.id,
            property_name: property.nombre,
            task_id: task.id,
            task_date: reservation.departureDate,
            guest_name: reservation.guestName,
            accommodation_id: reservation.accommodationId,
            status: reservation.status
          });
        } catch (taskError) {
          const errorMsg = `Error creando tarea para reserva ${reservation.id}: ${taskError.message}`;
          stats.errors.push(errorMsg);
          await logSyncError('task_creation_failed', errorMsg, {
            reservation_id: reservation.id,
            property_name: property.nombre,
            departure_date: reservation.departureDate
          }, syncLogId);
        }
      }

      const reservationData = {
        avantio_reservation_id: reservation.id,
        property_id: property.id,
        cliente_id: property.cliente_id,
        guest_name: reservation.guestName,
        guest_email: reservation.guestEmail,
        arrival_date: reservation.arrivalDate,
        departure_date: reservation.departureDate,
        reservation_date: reservation.reservationDate,
        cancellation_date: reservation.cancellationDate || null,
        nights: reservation.nights,
        status: reservation.status,
        adults: reservation.adults,
        children: reservation.children || 0,
        accommodation_id: reservation.accommodationId,
        accommodation_name: reservation.accommodationName,
        total_amount: reservation.totalAmount,
        currency: reservation.currency,
        notes: reservation.notes,
        task_id: taskId,
        last_sync_at: new Date().toISOString()
      };

      const { error: insertError } = await insertReservation(reservationData);
      if (insertError) {
        throw insertError;
      }

      stats.new_reservations++;
      
      if (!stats.reservations_details) stats.reservations_details = [];
      stats.reservations_details.push({
        reservation_id: reservation.id,
        property_name: property.nombre,
        guest_name: reservation.guestName,
        accommodation_id: reservation.accommodationId,
        status: reservation.status,
        arrival_date: reservation.arrivalDate,
        departure_date: reservation.departureDate,
        action: 'created'
      });

      

      // Check for one-night reservation with checkout tomorrow → send alert
      await this.checkAndSendOneNightAlert(reservation, property);
    } catch (error) {
      const errorMsg = `Error creando nueva reserva ${reservation.id}: ${error.message}`;
      console.error(`❌ ${errorMsg}`);
      stats.errors.push(errorMsg);
      await logSyncError('reservation_save_failed', errorMsg, {
        reservation_id: reservation.id,
        property_name: property.nombre
      }, syncLogId);
    }
  }

  private async handleExistingReservation(
    reservation: AvantioReservation,
    existingReservation: any,
    property: any,
    stats: SyncStats,
    syncLogId?: string | null
  ): Promise<void> {
    try {
      // Check if property/accommodation changed (reservation moved to different apartment)
      const propertyChanged = existingReservation.property_id !== property.id;
      
      if (propertyChanged) {
        console.log(`🏠 Cambio de apartamento detectado: ${existingReservation.accommodation_name || existingReservation.accommodation_id} -> ${reservation.accommodationName || reservation.accommodationId}`);
        
        // Delete old task and create new one for the new property
        if (existingReservation.task_id) {
          console.log(`🗑️ Eliminando tarea del apartamento anterior: ${existingReservation.task_id}`);
          try {
            await this.supabase
              .from('avantio_reservations')
              .update({ task_id: null })
              .eq('id', existingReservation.id);
            await deleteTask(existingReservation.task_id);
            stats.tasks_cancelled++;
            
            if (!stats.tasks_cancelled_details) stats.tasks_cancelled_details = [];
            stats.tasks_cancelled_details.push({
              reservation_id: reservation.id,
              property_name: existingReservation.accommodation_name || 'Unknown',
              task_id: existingReservation.task_id,
              task_date: reservation.departureDate,
              guest_name: reservation.guestName,
              accommodation_id: existingReservation.accommodation_id || '',
              status: 'property_changed'
            });
          } catch (taskError) {
            const errorMsg = `Error eliminando tarea antigua por cambio de apartamento para reserva ${reservation.id}: ${taskError.message}`;
            stats.errors.push(errorMsg);
            await logSyncError('task_deletion_failed', errorMsg, {
              reservation_id: reservation.id,
              task_id: existingReservation.task_id,
              old_property: existingReservation.accommodation_name,
              new_property: reservation.accommodationName
            }, syncLogId);
          }
        }
        
        // Create new task for the new property
        if (shouldCreateTaskForReservation(reservation)) {
          try {
            const task = await createTaskForReservation(reservation, property);
            existingReservation.task_id = task.id; // Update reference for later
            stats.tasks_created++;
            
            if (!stats.tasks_details) stats.tasks_details = [];
            stats.tasks_details.push({
              reservation_id: reservation.id,
              property_name: property.nombre,
              task_id: task.id,
              task_date: reservation.departureDate,
              guest_name: reservation.guestName,
              accommodation_id: reservation.accommodationId,
              status: reservation.status
            });
            console.log(`✅ Nueva tarea creada para apartamento ${property.nombre}`);
          } catch (taskError) {
            const errorMsg = `Error creando tarea para nuevo apartamento ${property.nombre}: ${taskError.message}`;
            stats.errors.push(errorMsg);
            await logSyncError('task_creation_failed', errorMsg, {
              reservation_id: reservation.id,
              property_name: property.nombre
            }, syncLogId);
          }
        }
      } else {
        // Same property - check if checkout date changed
        const dateChanged = existingReservation.departure_date !== reservation.departureDate;
        
        if (dateChanged && existingReservation.task_id) {
          console.log(`📅 Fecha de checkout cambió: ${existingReservation.departure_date} -> ${reservation.departureDate}`);
          try {
            await updateTaskDate(existingReservation.task_id, reservation.departureDate);
            stats.tasks_modified++;
            
            if (!stats.tasks_modified_details) stats.tasks_modified_details = [];
            stats.tasks_modified_details.push({
              reservation_id: reservation.id,
              property_name: property.nombre,
              task_id: existingReservation.task_id,
              task_date: reservation.departureDate,
              guest_name: reservation.guestName,
              accommodation_id: reservation.accommodationId,
              status: reservation.status
            });
          } catch (taskError) {
            const errorMsg = `Error actualizando tarea para reserva ${reservation.id}: ${taskError.message}`;
            stats.errors.push(errorMsg);
            await logSyncError('task_update_failed', errorMsg, {
              reservation_id: reservation.id,
              task_id: existingReservation.task_id,
              old_date: existingReservation.departure_date,
              new_date: reservation.departureDate
            }, syncLogId);
          }
        }

        // If no task exists yet but should have one, create it
        if (!existingReservation.task_id && shouldCreateTaskForReservation(reservation)) {
          try {
            const task = await createTaskForReservation(reservation, property);
            stats.tasks_created++;
            
            await updateReservation(existingReservation.id, { task_id: task.id });
            
            if (!stats.tasks_details) stats.tasks_details = [];
            stats.tasks_details.push({
              reservation_id: reservation.id,
              property_name: property.nombre,
              task_id: task.id,
              task_date: reservation.departureDate,
              guest_name: reservation.guestName,
              accommodation_id: reservation.accommodationId,
              status: reservation.status
            });
          } catch (taskError) {
            const errorMsg = `Error creando tarea faltante para reserva ${reservation.id}: ${taskError.message}`;
            stats.errors.push(errorMsg);
            await logSyncError('task_creation_failed', errorMsg, {
              reservation_id: reservation.id,
              property_name: property.nombre
            }, syncLogId);
          }
        }

        // Handle REQUESTED status changes on task name
        if (existingReservation.task_id) {
          const statusChanged = existingReservation.status?.toUpperCase() !== reservation.status.toUpperCase();
          if (statusChanged) {
            const expectedName = getTaskPropertyName(property.nombre, property.codigo, reservation.status);
            const currentTaskName = existingReservation.tasks?.property;
            if (currentTaskName && currentTaskName !== expectedName) {
              try {
                await updateTaskPropertyName(existingReservation.task_id, expectedName);
                console.log(`📝 Nombre de tarea actualizado: "${currentTaskName}" -> "${expectedName}"`);
                stats.tasks_modified++;
              } catch (taskError) {
                const errorMsg = `Error actualizando nombre de tarea para reserva ${reservation.id}: ${taskError.message}`;
                stats.errors.push(errorMsg);
              }
            }
          }
        }
      }

      const reservationData: any = {
        guest_name: reservation.guestName,
        guest_email: reservation.guestEmail,
        arrival_date: reservation.arrivalDate,
        departure_date: reservation.departureDate,
        nights: reservation.nights,
        status: reservation.status,
        adults: reservation.adults,
        children: reservation.children || 0,
        total_amount: reservation.totalAmount,
        notes: reservation.notes,
        accommodation_id: reservation.accommodationId,
        accommodation_name: reservation.accommodationName,
        property_id: property.id,
        last_sync_at: new Date().toISOString()
      };

      // Include new task_id if property changed
      if (propertyChanged && existingReservation.task_id) {
        reservationData.task_id = existingReservation.task_id;
      }

      await updateReservation(existingReservation.id, reservationData);
      stats.updated_reservations++;
      
      if (!stats.reservations_details) stats.reservations_details = [];
      stats.reservations_details.push({
        reservation_id: reservation.id,
        property_name: property.nombre,
        guest_name: reservation.guestName,
        accommodation_id: reservation.accommodationId,
        status: reservation.status,
        arrival_date: reservation.arrivalDate,
        departure_date: reservation.departureDate,
        action: 'updated'
      });

      
    } catch (error) {
      const errorMsg = `Error actualizando reserva ${reservation.id}: ${error.message}`;
      console.error(`❌ ${errorMsg}`);
      stats.errors.push(errorMsg);
      await logSyncError('reservation_save_failed', errorMsg, {
        reservation_id: reservation.id,
        property_name: property.nombre
      }, syncLogId);
    }
  }

  private async handleCancelledReservation(
    reservation: AvantioReservation,
    existingReservation: any,
    property: any,
    stats: SyncStats,
    syncLogId?: string | null
  ): Promise<void> {
    try {
      // Logging silenciado: alta cardinalidad provocaba CPU Time exceeded.
      if (existingReservation.task_id) {
        
        try {
          // Fetch task details to check if a cleaner is assigned
          const { data: taskData } = await this.supabase
            .from('tasks')
            .select('*, cleaners(id, name, email)')
            .eq('id', existingReservation.task_id)
            .single();

          const deleted = await deleteTaskIfPending(existingReservation.task_id);
          if (!deleted) {
            console.log(`🛡️ Tarea ${existingReservation.task_id} conservada tras cancelación Avantio: ya comenzó, terminó o su estado no es seguro para borrar`);
          } else {
            const { error: unlinkError } = await this.supabase
              .from('avantio_reservations')
              .update({ task_id: null })
              .eq('id', existingReservation.id);
            if (unlinkError) throw unlinkError;

          stats.tasks_cancelled++;

          // Send cancellation email if cleaner was assigned
          if (taskData?.cleaner_id && taskData?.cleaners?.email) {
            console.log(`📧 Enviando email de cancelación a ${taskData.cleaners.name} (${taskData.cleaners.email})`);
            try {
              const { error: emailError } = await this.supabase.functions.invoke('send-task-unassignment-email', {
                body: {
                  taskId: existingReservation.task_id,
                  cleanerEmail: taskData.cleaners.email,
                  cleanerName: taskData.cleaners.name,
                  taskData: {
                    property: taskData.property || property.nombre,
                    address: taskData.address || property.direccion || '',
                    date: taskData.date || reservation.departureDate,
                    startTime: taskData.start_time || '',
                    endTime: taskData.end_time || '',
                    type: taskData.service_type || '',
                    notes: `Reserva cancelada por sincronización Avantio. Huésped: ${reservation.guestName}`
                  },
                  reason: 'cancelled'
                }
              });
              if (emailError) throw emailError;
              console.log(`✅ Email de cancelación enviado a ${taskData.cleaners.name}`);
            } catch (emailError) {
              console.error(`❌ Error enviando email de cancelación:`, emailError);
            }
          }
          
          if (!stats.tasks_cancelled_details) stats.tasks_cancelled_details = [];
          stats.tasks_cancelled_details.push({
            reservation_id: reservation.id,
            property_name: property.nombre,
            task_id: existingReservation.task_id,
            task_date: reservation.departureDate,
            guest_name: reservation.guestName,
            accommodation_id: reservation.accommodationId,
            status: 'cancelled'
          });
          }
        } catch (taskError) {
          const errorMsg = `Error eliminando tarea ${existingReservation.task_id}: ${taskError.message}`;
          stats.errors.push(errorMsg);
          await logSyncError('task_deletion_failed', errorMsg, {
            reservation_id: reservation.id,
            task_id: existingReservation.task_id,
            property_name: property.nombre
          }, syncLogId);
        }
      }

      await updateReservation(existingReservation.id, {
        status: 'cancelled',
        cancellation_date: reservation.cancellationDate || new Date().toISOString(),
        last_sync_at: new Date().toISOString()
      });

      stats.cancelled_reservations++;
      
      if (!stats.reservations_details) stats.reservations_details = [];
      stats.reservations_details.push({
        reservation_id: reservation.id,
        property_name: property.nombre,
        guest_name: reservation.guestName,
        accommodation_id: reservation.accommodationId,
        status: 'cancelled',
        arrival_date: reservation.arrivalDate,
        departure_date: reservation.departureDate,
        action: 'cancelled'
      });

      
    } catch (error) {
      const errorMsg = `Error procesando cancelación ${reservation.id}: ${error.message}`;
      console.error(`❌ ${errorMsg}`);
      stats.errors.push(errorMsg);
      await logSyncError('reservation_save_failed', errorMsg, {
        reservation_id: reservation.id,
        property_name: property.nombre
      }, syncLogId);
    }
  }

  private async createCancelledReservation(
    reservation: AvantioReservation,
    property: any,
    stats: SyncStats,
    syncLogId?: string | null
  ): Promise<void> {
    try {
      const reservationData = {
        avantio_reservation_id: reservation.id,
        property_id: property.id,
        cliente_id: property.cliente_id,
        guest_name: reservation.guestName,
        guest_email: reservation.guestEmail,
        arrival_date: reservation.arrivalDate,
        departure_date: reservation.departureDate,
        reservation_date: reservation.reservationDate,
        cancellation_date: reservation.cancellationDate || new Date().toISOString(),
        nights: reservation.nights,
        status: 'cancelled',
        adults: reservation.adults,
        children: reservation.children || 0,
        accommodation_id: reservation.accommodationId,
        accommodation_name: reservation.accommodationName,
        task_id: null,
        last_sync_at: new Date().toISOString()
      };

      await insertReservation(reservationData);
      stats.cancelled_reservations++;
      
      
    } catch (error) {
      const errorMsg = `Error creando reserva cancelada ${reservation.id}: ${error.message}`;
      console.error(`❌ ${errorMsg}`);
      stats.errors.push(errorMsg);
      await logSyncError('reservation_save_failed', errorMsg, {
        reservation_id: reservation.id,
        property_name: property.nombre
      }, syncLogId);
    }
  }

  /**
   * Checks if a new reservation is a one-night stay with checkout tomorrow,
   * and sends an alert email if so.
   * 
   * SISTEMA ANTI-SPAM:
   * 1. Ignora estados no confirmados (REQUESTED, PENDING, TENTATIVE)
   * 2. Deduplicación dura: solo 1 alerta por (propiedad + fecha checkout)
   *    usando la tabla avantio_alert_log con índice único.
   */
  private async checkAndSendOneNightAlert(
    reservation: AvantioReservation,
    property: any
  ): Promise<void> {
    if (reservation.nights !== 1) return;

    // FILTRO 1: Solo reservas confirmadas disparan alertas
    const statusUpper = reservation.status.toUpperCase();
    const NON_CONFIRMED_STATUSES = ['REQUESTED', 'PENDING', 'TENTATIVE', 'CANCELLED', 'CANCELED', 'UNAVAILABLE', 'UNAVALIABLE'];
    if (NON_CONFIRMED_STATUSES.includes(statusUpper)) {
      console.log(`⏭️ Alerta omitida para reserva ${reservation.id}: estado no confirmado (${reservation.status})`);
      return;
    }

    // Ventana temporal: alertar de cualquier reserva de 1 noche cuyo checkout
    // caiga entre HOY y HOY+30 días (zona horaria Europe/Madrid).
    const nowMadrid = new Date(new Date().toLocaleString('en-US', { timeZone: 'Europe/Madrid' }));
    const todayMadrid = new Date(nowMadrid.getFullYear(), nowMadrid.getMonth(), nowMadrid.getDate());
    const maxDateMadrid = new Date(todayMadrid);
    maxDateMadrid.setDate(maxDateMadrid.getDate() + 30);

    const fmt = (d: Date) =>
      `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
    const todayStr = fmt(todayMadrid);
    const maxStr = fmt(maxDateMadrid);

    if (reservation.departureDate < todayStr || reservation.departureDate > maxStr) return;

    // FILTRO 2: Deduplicación atómica. Insertar primero en avantio_alert_log.
    // Si ya existe una alerta para (one_night, property, checkout_date), el INSERT falla
    // por el índice único y NO se envía email duplicado.
    const { data: alertRecord, error: dedupError } = await this.supabase
      .from('avantio_alert_log')
      .insert({
        alert_type: 'one_night',
        property_id: property.id,
        accommodation_id: reservation.accommodationId,
        reference_date: reservation.departureDate,
        reservation_id: reservation.id,
        metadata: {
          guest_name: reservation.guestName,
          status: reservation.status,
          arrival_date: reservation.arrivalDate,
        }
      })
      .select()
      .single();

    if (dedupError) {
      // Código 23505 = unique_violation → ya se envió esta alerta hoy
      if (dedupError.code === '23505') {
        console.log(`🔇 Alerta duplicada bloqueada (ya enviada): ${property.nombre} → checkout ${reservation.departureDate}`);
        return;
      }
      console.error(`⚠️ Error en deduplicación de alertas:`, dedupError);
      // En caso de error de DB, NO enviamos para evitar spam si la tabla falla
      return;
    }

    console.log(`⚡ Reserva de 1 noche detectada con checkout ${reservation.departureDate}: ${reservation.id} - ${property.nombre}`);

    try {
      const { data: emailResp } = await this.supabase.functions.invoke('send-one-night-alert', {
        body: {
          reservationId: reservation.id,
          propertyName: property.nombre,
          guestName: reservation.guestName,
          arrivalDate: reservation.arrivalDate,
          departureDate: reservation.departureDate,
          accommodationId: reservation.accommodationId,
          status: reservation.status,
          adults: reservation.adults,
          children: reservation.children || 0,
          notes: reservation.notes || null,
        }
      });
      
      // Guardar el email_id devuelto por Resend
      if (emailResp?.emailId && alertRecord?.id) {
        await this.supabase
          .from('avantio_alert_log')
          .update({ email_id: emailResp.emailId })
          .eq('id', alertRecord.id);
      }
      
      console.log(`✅ Alerta de 1 noche enviada para reserva ${reservation.id}`);
    } catch (alertError) {
      console.error(`❌ Error enviando alerta de 1 noche para reserva ${reservation.id}:`, alertError);
      // Rollback: si el email falló, borrar el log para permitir reintento
      if (alertRecord?.id) {
        await this.supabase.from('avantio_alert_log').delete().eq('id', alertRecord.id);
      }
    }
  }
}

import { createClient } from "npm:@supabase/supabase-js@2.50.0";
import { AvantioReservation } from './types.ts';
import { canDeleteTaskAfterPmsCancellation } from '../_shared/taskCancellationPolicy.ts';

const supabaseUrl = Deno.env.get('SUPABASE_URL')!;
const supabaseServiceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;
const supabase = createClient(supabaseUrl, supabaseServiceKey);

// Client ID for Turquoise Apartments SL
const TURQUOISE_CLIENT_ID = '669948a6-e5c3-4a73-a151-6ccca5c82adf';

// In-memory cache of all Turquoise properties, populated once per sync.
// Eliminates thousands of redundant SELECT queries during reservation processing.
let propertiesCache: any[] | null = null;
let cacheById: Map<string, any> = new Map();
let cacheByName: Map<string, any> = new Map();
let cacheByCode: Map<string, any> = new Map();

// In-memory cache of existing avantio_reservations, keyed by avantio_reservation_id.
// Avoids one SELECT query per reservation processed.
let reservationsCache: Map<string, any> = new Map();

// In-memory cache of existing tasks for the sync window, keyed by `${propiedad_id}_${date}`.
// Avoids one SELECT query per new task creation (deduplication check).
let tasksCache: Map<string, any> = new Map();

export async function preloadReservationsAndTasksCache(fromDate: string, toDate: string) {
  console.log('🗄️ Precargando caché de reservas y tareas...');
  reservationsCache.clear();
  tasksCache.clear();

  // Load ALL avantio_reservations in window with pagination (Supabase default limit is 1000).
  // CRITICAL: without pagination, missing rows fall back to per-reservation DB queries → CPU exhaustion.
  const PAGE = 1000;
  let from = 0;
  let totalLoaded = 0;
  while (true) {
    const { data: page, error: rErr } = await supabase
      .from('avantio_reservations')
      .select('*, tasks(*)')
      .gte('departure_date', fromDate)
      .lte('departure_date', toDate)
      .range(from, from + PAGE - 1);

    if (rErr) {
      console.error('❌ Error precargando reservas:', rErr);
      break;
    }
    if (!page || page.length === 0) break;

    for (const r of page) {
      reservationsCache.set(String(r.avantio_reservation_id), r);
    }
    totalLoaded += page.length;
    if (page.length < PAGE) break;
    from += PAGE;
  }

  // Load all green (Avantio) tasks in the sync window for dedup
  const { data: tasks, error: tErr } = await supabase
    .from('tasks')
    .select('id, propiedad_id, date, property')
    .eq('background_color', '#10B981')
    .gte('date', fromDate)
    .lte('date', toDate)
    .neq('status', 'cancelled');

  if (tErr) {
    console.error('❌ Error precargando tareas:', tErr);
  } else if (tasks) {
    for (const t of tasks) {
      if (t.propiedad_id && t.date) {
        tasksCache.set(`${t.propiedad_id}_${t.date}`, t);
      }
    }
  }

  console.log(`✅ Caché reservas/tareas: ${totalLoaded} reservas, ${tasksCache.size} tareas`);
}

export function clearReservationsAndTasksCache() {
  reservationsCache.clear();
  tasksCache.clear();
}

export function getCachedReservation(avantioReservationId: string) {
  return reservationsCache.get(String(avantioReservationId)) || null;
}

/**
 * Preload all Turquoise properties into memory.
 * MUST be called once at the start of each sync to avoid CPU exhaustion.
 */
export async function preloadPropertiesCache() {
  console.log('🗄️ Precargando caché de propiedades...');
  const { data, error } = await supabase
    .from('properties')
    .select('*')
    .eq('cliente_id', TURQUOISE_CLIENT_ID);

  if (error) {
    console.error('❌ Error precargando propiedades:', error);
    throw error;
  }

  propertiesCache = data || [];
  cacheById.clear();
  cacheByName.clear();
  cacheByCode.clear();

  for (const prop of propertiesCache) {
    if (prop.avantio_accommodation_id) {
      cacheById.set(String(prop.avantio_accommodation_id), prop);
    }
    if (prop.nombre) {
      cacheByName.set(prop.nombre.toLowerCase().trim(), prop);
    }
    if (prop.codigo) {
      cacheByCode.set(prop.codigo.toLowerCase().trim(), prop);
    }
  }

  console.log(`✅ Caché cargado: ${propertiesCache.length} propiedades (${cacheById.size} con avantio_id, ${cacheByCode.size} con código)`);
}

/**
 * Clear the cache (called at end of sync to free memory).
 */
export function clearPropertiesCache() {
  propertiesCache = null;
  cacheById.clear();
  cacheByName.clear();
  cacheByCode.clear();
}

/**
 * Find property by exact match using IN-MEMORY CACHE.
 * Order: avantio_accommodation_id > exact name > exact code > name as code > strip C prefix
 *
 * NOTE: Cache must be preloaded with preloadPropertiesCache() before calling this.
 * Background updates of avantio_accommodation_id are fire-and-forget to avoid CPU stalls.
 */
export async function findPropertyByAvantioId(
  accommodationId: string,
  accommodationName?: string,
  accommodationInternalName?: string
) {
  if (!propertiesCache) {
    console.warn('⚠️ Caché no precargado, recargando...');
    await preloadPropertiesCache();
  }

  // 1. Search by avantio_accommodation_id (exact)
  if (accommodationId) {
    const prop = cacheById.get(String(accommodationId));
    if (prop) return prop;
  }

  // Helper: persist avantio_accommodation_id in background (fire-and-forget)
  const persistAvantioId = (prop: any, accId: string, accName?: string) => {
    if (!accId || prop.avantio_accommodation_id) return;
    // Update cache immediately
    prop.avantio_accommodation_id = accId;
    cacheById.set(String(accId), prop);
    // Persist to DB in background (non-blocking)
    supabase
      .from('properties')
      .update({ avantio_accommodation_id: accId, avantio_accommodation_name: accName || prop.nombre })
      .eq('id', prop.id)
      .then(() => {})
      .catch((err) => console.error(`❌ Error persistiendo avantio_id para ${prop.nombre}:`, err));
  };

  // 2. Search by exact name (case-insensitive)
  if (accommodationName) {
    const prop = cacheByName.get(accommodationName.toLowerCase().trim());
    if (prop) {
      persistAvantioId(prop, accommodationId, accommodationName);
      return prop;
    }
  }

  // 3. Search by exact code
  if (accommodationInternalName) {
    const prop = cacheByCode.get(accommodationInternalName.toLowerCase().trim());
    if (prop) {
      persistAvantioId(prop, accommodationId, accommodationName);
      return prop;
    }
  }

  // 4. Try matching accommodationName directly as codigo
  if (accommodationName) {
    const prop = cacheByCode.get(accommodationName.toLowerCase().trim());
    if (prop) {
      persistAvantioId(prop, accommodationId, accommodationName);
      return prop;
    }
  }

  // 5. Try stripping C prefix (CMD18.5 -> MD18.5)
  if (accommodationName) {
    const stripped = accommodationName.replace(/^C/, '').toLowerCase().trim();
    if (stripped !== accommodationName.toLowerCase().trim()) {
      const prop = cacheByCode.get(stripped);
      if (prop) {
        persistAvantioId(prop, accommodationId, accommodationName);
        return prop;
      }
    }
  }

  console.log(`❌ Propiedad no encontrada: ID="${accommodationId}", nombre="${accommodationName || 'N/A'}", código="${accommodationInternalName || 'N/A'}"`);
  return null;
}

/**
 * Validate that property and client exist
 */
export async function validatePropertyAndClient(propertyId: string, clientId: string): Promise<{ valid: boolean; errors: string[] }> {
  const errors: string[] = [];
  
  const { data: property, error: propError } = await supabase
    .from('properties')
    .select('id, nombre')
    .eq('id', propertyId)
    .single();
    
  if (propError || !property) {
    errors.push(`Propiedad con ID ${propertyId} no existe`);
  }
  
  const { data: client, error: clientError } = await supabase
    .from('clients')
    .select('id, nombre')
    .eq('id', clientId)
    .single();
    
  if (clientError || !client) {
    errors.push(`Cliente con ID ${clientId} no existe`);
  }
  
  return { valid: errors.length === 0, errors };
}

/**
 * Create task for a reservation (cleaning on checkout day)
 */
export function getTaskPropertyName(propertyName: string, propertyCodigo: string, reservationStatus: string): string {
  const baseName = propertyCodigo ? `${propertyCodigo} ${propertyName}` : propertyName;
  const isRequested = reservationStatus.toUpperCase() === 'REQUESTED';
  return isRequested ? `POSIBLE - ${baseName}` : baseName;
}

export async function updateTaskPropertyName(taskId: string, propertyName: string) {
  console.log(`📝 Actualizando nombre de tarea ${taskId} a "${propertyName}"`);
  const { error } = await supabase
    .from('tasks')
    .update({ property: propertyName, updated_at: new Date().toISOString() })
    .eq('id', taskId);
  if (error) {
    console.error('❌ Error actualizando nombre de tarea:', error);
    throw error;
  }
}

export async function createTaskForReservation(reservation: AvantioReservation, property: any) {
  // DEDUPLICATION: Check in-memory cache first (set populated by preloadReservationsAndTasksCache)
  const cacheKey = `${property.id}_${reservation.departureDate}`;
  const cachedTask = tasksCache.get(cacheKey);
  if (cachedTask) {
    return cachedTask;
  }

  const startTime = '11:00';
  const durationMinutes = property.duracion_servicio || 60;
  const endHour = 11 + Math.floor(durationMinutes / 60);
  const endMinute = durationMinutes % 60;
  const endTime = `${endHour.toString().padStart(2, '0')}:${endMinute.toString().padStart(2, '0')}`;

  const taskPropertyName = getTaskPropertyName(property.nombre, property.codigo, reservation.status);

  const taskData = {
    property: taskPropertyName,
    address: property.direccion,
    date: reservation.departureDate,
    start_time: startTime,
    end_time: endTime,
    check_in: property.check_in_predeterminado,
    check_out: property.check_out_predeterminado,
    type: 'limpieza-turistica',
    status: 'pending',
    duracion: property.duracion_servicio,
    coste: property.coste_servicio,
    propiedad_id: property.id,
    cliente_id: property.cliente_id,
    sede_id: property.sede_id,
    cleaner: null,
    cleaner_id: null,
    background_color: '#10B981'
  };

  const { data: task, error } = await supabase
    .from('tasks')
    .insert(taskData)
    .select()
    .single();

  if (error) {
    console.error('❌ Error creando tarea:', error);
    throw error;
  }

  // Add to cache so subsequent reservations for the same property/date reuse it
  tasksCache.set(cacheKey, task);
  return task;
}

/**
 * Get existing reservation by Avantio ID.
 * Uses in-memory cache populated by preloadReservationsAndTasksCache to avoid per-reservation queries.
 */
export async function getExistingReservation(reservationId: string) {
  const cached = reservationsCache.get(String(reservationId));
  if (cached !== undefined) return cached;

  // Fallback to DB query if not in cache (shouldn't happen for in-window data)
  const { data: existingReservation } = await supabase
    .from('avantio_reservations')
    .select('*, tasks(*)')
    .eq('avantio_reservation_id', reservationId)
    .single();

  return existingReservation;
}

