}

/**
 * Log a sync error to avantio_sync_errors table
 */
export async function logSyncError(
  errorType: string,
  errorMessage: string,
  errorDetails?: Record<string, any>,
  syncLogId?: string | null
) {
  try {
    await supabase
      .from('avantio_sync_errors')
      .insert({
        sync_log_id: syncLogId || null,
        error_type: errorType,
        error_message: errorMessage,
        error_details: errorDetails || null,
        resolved: false
      });
    console.log(`📝 Error registrado en avantio_sync_errors: [${errorType}] ${errorMessage}`);
  } catch (err) {
    console.error('❌ Error registrando en avantio_sync_errors:', err);
  }
}

const DELETABLE_TASK_STATUS = 'pending';

export function normalizeTaskStatus(status: string | null | undefined): string {
  return String(status ?? '')
    .trim()
    .toLowerCase()
    .replace(/_/g, '-');
}

/**
 * PMS cancellations may only remove tasks that have not started yet.
 * Unknown states are preserved deliberately: destructive integrations fail closed.
 */
export function canDeleteTaskAfterPmsCancellation(
  status: string | null | undefined,
): boolean {
  return normalizeTaskStatus(status) === DELETABLE_TASK_STATUS;
}

import { AvantioReservation } from './types.ts';

export const TASK_CREATION_HORIZON_DAYS = 30;

/**
 * Determines if a task should be created for a reservation.
 * Creates tasks only for non-cancelled reservations whose checkout is inside
 * the operational sync horizon. Reservations arriving in that horizon may be
 * stored for future-entry display even when their checkout is later.
 */
export function shouldCreateTaskForReservation(reservation: AvantioReservation): boolean {
  const statusUpper = reservation.status.toUpperCase();
  
  // Cancelled or unavailable reservations don't get tasks
  if (statusUpper === 'CANCELLED' || statusUpper === 'CANCELED' || statusUpper === 'UNAVAILABLE' || statusUpper === 'UNAVALIABLE') {
    return false;
  }
  
  // REQUESTED = solicitud tentativa no confirmada. No genera tarea ni alerta.
  // Solo se crean tareas para reservas confirmadas (CONFIRMED, BOOKED, etc.)
  if (statusUpper === 'REQUESTED' || statusUpper === 'PENDING' || statusUpper === 'TENTATIVE') {
    return false;
  }
  
  // If has cancellation date, don't create task
  if (reservation.cancellationDate) {
    return false;
  }
  
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const checkoutDate = new Date(reservation.departureDate);
  
  if (checkoutDate < today) {
    return false;
  }

  const lastTaskDate = new Date(today);
  lastTaskDate.setDate(lastTaskDate.getDate() + TASK_CREATION_HORIZON_DAYS);
  if (checkoutDate > lastTaskDate) {
    return false;
  }
  
  return true;
}

import { SyncStats } from './types.ts';

export class ResponseBuilder {
  static buildSuccessResponse(
    stats: SyncStats,
    startDate: string,
    endDate: string,
    totalReservations: number
  ) {
    return {
      success: true,
      message: 'Sincronización con Avantio completada exitosamente',
      dateRange: { start: startDate, end: endDate },
      stats: {
        reservationsProcessed: stats.reservations_processed,
        newReservations: stats.new_reservations,
        updatedReservations: stats.updated_reservations,
        cancelledReservations: stats.cancelled_reservations,
        tasksCreated: stats.tasks_created,
        tasksCancelled: stats.tasks_cancelled,
        tasksModified: stats.tasks_modified,
        errorsCount: stats.errors.length
      },
      details: {
        tasks: stats.tasks_details,
        tasksCancelled: stats.tasks_cancelled_details,
        tasksModified: stats.tasks_modified_details,
        reservations: stats.reservations_details
      },
      errors: stats.errors.length > 0 ? stats.errors : null,
      timestamp: new Date().toISOString()
    };
  }

  static buildErrorResponse(error: Error, stats: SyncStats) {
    return {
      success: false,
      message: 'Error durante la sincronización con Avantio',
      error: error.message,
      stats: {
        reservationsProcessed: stats.reservations_processed,
        newReservations: stats.new_reservations,
        updatedReservations: stats.updated_reservations,
        cancelledReservations: stats.cancelled_reservations,
        tasksCreated: stats.tasks_created,
        tasksCancelled: stats.tasks_cancelled,
        tasksModified: stats.tasks_modified,
        errorsCount: stats.errors.length
      },
      allErrors: stats.errors,
      timestamp: new Date().toISOString()
    };
  }

  static buildCriticalErrorResponse(error: Error) {
    return {
      success: false,
      message: 'Error crítico en la sincronización con Avantio',
      error: error.message,
      timestamp: new Date().toISOString()
    };
  }

  static buildConfigurationErrorResponse() {
    return {
      success: false,
      message: 'Avantio no está configurado',
      error: 'Falta el token de API de Avantio. Por favor, configura AVANTIO_API_TOKEN en los secretos de Supabase.',
      requiredSecrets: [
        'AVANTIO_API_TOKEN - Token de autenticación de la API de Avantio PMS v1'
      ],
      timestamp: new Date().toISOString()
    };
  }
}
